// Thriftly Official SVG Logo Component (Generated from NoText.svg)

import React from "react";
import Svg, { G, Path } from "react-native-svg";

// Deteksi warna biru logo untuk diubah ke putih pada dark mode  //
const getThemeColor = (hex, darkMode) => {
  if (!darkMode) return hex;

  // Ubah format hex  //
  const cleanHex = hex.replace("#", "");
  let r, g, b;

  if (cleanHex.length === 3) {
    r = parseInt(cleanHex[0] + cleanHex[0], 16);
    g = parseInt(cleanHex[1] + cleanHex[1], 16);
    b = parseInt(cleanHex[2] + cleanHex[2], 16);
  } else if (cleanHex.length === 6) {
    r = parseInt(cleanHex.substring(0, 2), 16);
    g = parseInt(cleanHex.substring(2, 4), 16);
    b = parseInt(cleanHex.substring(4, 6), 16);
  } else {
    return hex;
  }

  // Cek apakah dominan biru  //
  const isBlue = b > r && b > g - 30;

  if (isBlue) {
    return "#FFFFFF"; // Ubah biru ke putih  //
  }

  return hex;
};

